import{_ as a,o as r,c as t,ah as i}from"./chunks/framework.DjU4PSOm.js";const m=JSON.parse('{"title":"📅 2026-10-03 (토) — 6주차 온라인 강의(6-1, 6-2) 요약 (강의 제공 자료, 영문+국문)","description":"","frontmatter":{},"headers":[{"level":2,"title":"English Summary","slug":"english-summary","link":"#english-summary","children":[]},{"level":2,"title":"한글 요약","slug":"한글-요약","link":"#한글-요약","children":[]}],"relativePath":"philosophy/Ethics/Raw-Transcripts/2026-10-03_week6_online-summary.md","filePath":"philosophy/Ethics/Raw-Transcripts/2026-10-03_week6_online-summary.md"}'),n={name:"philosophy/Ethics/Raw-Transcripts/2026-10-03_week6_online-summary.md"};function s(o,e,l,c,h,u){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="📅-2026-10-03-토-—-6주차-온라인-강의-6-1-6-2-요약-강의-제공-자료-영문-국문" tabindex="-1">📅 2026-10-03 (토) — 6주차 온라인 강의(6-1, 6-2) 요약 (강의 제공 자료, 영문+국문) <a class="header-anchor" href="#📅-2026-10-03-토-—-6주차-온라인-강의-6-1-6-2-요약-강의-제공-자료-영문-국문" aria-label="Permalink to &quot;📅 2026-10-03 (토) — 6주차 온라인 강의(6-1, 6-2) 요약 (강의 제공 자료, 영문+국문)&quot;">​</a></h1><p>윤리학 | 001 분반 (Ethics | 001 Section) - 6주차 (온라인 강의 6-1, 6-2)<br> 윤지영 교수</p><blockquote><p>강의 자료/요약 무단 복제 및 유포 시 법적 책임이 발생할 수 있습니다.</p></blockquote><hr><h2 id="english-summary" tabindex="-1">English Summary <a class="header-anchor" href="#english-summary" aria-label="Permalink to &quot;English Summary&quot;">​</a></h2><p>This lecture introduces Jeremy Bentham’s utilitarianismby contrasting it with Kantian<br> deontological ethics. Whereas Kant evaluates an action mainly by the principle or maxim<br> from which it is performed, Bentham asks us to examine its actual or expected<br> consequences: how much pleasure it produces, how much pain it prevents, how many<br> people are affected, how certain the effects are, and how long they last.<br> The lecture first reviews the main ideas of Kantian ethics: the good will, duty, and the<br> categorical imperative, including the Formula of Universal Law, the Formula of Humanity,<br> and the Formula of Autonomy. Kant’s ethics protects rational agency, dignity, and autonomy<br> and resists using persons merely as means. However, the lecture also examines several<br> difficulties: the moral importance of consequences, conflicts between duties, emergency and<br> public-policy decisions, dependency and unequal care burdens, and the moral status of non-<br> human animals.<br> Bentham offers a different starting point. Rather than asking what principle every rational<br> agent could accept as universal law, he asks which action or policy will produce the greatest<br> overall balance of pleasure over pain for everyone affected. In this sense, Kant begins<br> from duty, while Bentham begins from welfare; Kant evaluates maxims, while Bentham<br> evaluates the tendencies and consequences of actions.<br> Bentham’s ethical theory is presented as a form of consequentialismand hedonism.<br> Consequentialism evaluates actions according to the effects they produce or are expected to<br> produce. Hedonism holds that pleasure is intrinsically good and pain intrinsically bad. The<br> lecture also distinguishes psychological hedonism, a descriptive claim that human beings<br> seek pleasure and avoid pain, from ethical hedonism, a normative claim that we ought to<br> increase pleasure and reduce pain.<br> A central concept is the principle of utility. Utility does not simply mean practical<br> usefulness; it refers to the tendency of an action to produce benefit, advantage, pleasure,<br> good, or happiness, and to prevent mischief, pain, evil, or unhappiness. In simplified form,<br> the moral value of an action is determined by the total expected balance of pleasure over<br> pain among everyone affected.</p><p>Bentham’s theory is called quantitative utilitarianismbecause pleasures and pains are<br> compared primarily in terms of their amount and dimensions, rather than being ranked<br> according to an intrinsic hierarchy of “higher” and “lower” pleasures. An intellectual pleasure<br> is not automatically superior to a bodily pleasure; its greater value must be explained<br> through features such as duration, future effects, and freedom from accompanying pain.<br> The lecture then introduces the seven dimensions of value that structure Bentham’s felicific<br> calculus:<br> 1.<br> Intensity– how strong the pleasure or pain is.<br> 2.<br> Duration– how long it lasts.<br> 3.<br> Certainty– how likely it is to occur.<br> 4.<br> Propinquity– how near in time it is.<br> 5.<br> Fecundity– how likely it is to be followed by further pleasures or pains.<br> 6.<br> Purity– how unlikely it is to be followed by the opposite kind of sensation.<br> 7.<br> Extent– how many persons are affected.<br> These dimensions do not function as a perfectly precise mathematical formula. Rather, they<br> provide a structured method for comparing the likely consequences of different actions and<br> policies. The lecture illustrates this by comparing such cases as public health programmes,<br> education, addictive digital platforms, punishment, climate change, and competing uses of<br> university resources.<br> Bentham’s utilitarianism also contains an important principle of impartial aggregation. One<br> person’s pleasure does not count more simply because it is “mine,” and the suffering of the<br> poor, prisoners, or non-human animals cannot be ignored merely because they lack social<br> or political power. This gives utilitarianism an egalitarian potential. At the same time,<br> however, aggregation raises a serious problem: the suffering of a minority may be<br> outweighed by the pleasure of a majority, and individuals do not necessarily possess<br> inviolable rights within the calculation.<br> Finally, the lecture places Bentham in the context of the Enlightenment, legal reform, and<br> the rise of measurement and administration. Bentham rejected the idea that traditions<br> and laws were justified merely because they were old. He argued that institutions should be<br> judged by whether they reduce suffering and promote happiness. Quantification could</p><p>challenge privilege and arbitrary authority, but the lecture also emphasizes that<br> measurement can conceal assumptions, reproduce social biases, and leave some experiences<br> invisible.<br> Core idea: Bentham transforms moral judgment into a comparative evaluation of<br> experienced consequences. His ethics asks not simply whether an action conforms to a<br> universal principle, but how much pleasure and pain it is likely to produce, for whom, for<br> how long, and with what future effects.</p><h2 id="한글-요약" tabindex="-1">한글 요약 <a class="header-anchor" href="#한글-요약" aria-label="Permalink to &quot;한글 요약&quot;">​</a></h2><p>이 강의는 칸트의 의무론적 윤리학에서 제러미 벤담의 공리주의로 이행하는 과정을 다룬다.<br> 칸트가 행위의 도덕적 가치를 행위자가 따르는 원칙과 준칙(maxim)에서 찾는다면, 벤담은<br> 행위와 정책이 실제로 산출하거나 산출할 것으로 예상되는 결과를 평가한다. 즉 얼마나 많<br> 은 쾌락을 낳는지, 얼마나 많은 고통을 방지하는지, 몇 명에게 영향을 미치는지, 그 효과가<br> 얼마나 확실하고 얼마나 오래 지속되는지를 묻는다.<br> 먼저 강의는 칸트 윤리학의 핵심 개념인 선의지, 의무, 정언명령을 복습한다. 보편법칙의 정<br> 식, 인간성의 정식, 자율성의 정식은 인간의 합리적 행위 능력, 자율성, 존엄성을 보호하고<br> 타인을 단순한 수단으로 대하는 것을 금지한다. 그러나 동시에 이 강의는 칸트 윤리학이 직<br> 면하는 문제들, 즉 결과의 도덕적 중요성, 의무 충돌, 긴급 상황과 공공정책, 의존성과 돌봄<br> 의 불평등, 비인간 동물의 도덕적 지위 등을 검토한다.<br> 이에 비해 벤담은 전혀 다른 출발점을 제시한다. 칸트가 “모든 이성적 행위자가 보편법칙으<br> 로 받아들일 수 있는 원칙은 무엇인가?”를 묻는다면, 벤담은 “모든 영향을 받는 사람들에게<br> 쾌락이 고통보다 최대한 많이 우세하도록 만드는 행위나 정책은 무엇인가?”를 묻는다. 따라<br> 서 칸트가 의무와 준칙에서 출발한다면, 벤담은 복지와 경험된 결과에서 출발한다.<br> 벤담의 윤리학은 결과주의(consequentialism)이자 쾌락주의(hedonism)이다. 결과주의는 행위<br> 가 낳는 또는 낳을 것으로 예상되는 결과에 따라 행위를 평가한다. 쾌락주의는 쾌락은 그<br> 자체로 선하고, 고통은 그 자체로 악하다고 본다. 이 강의는 또한 인간이 실제로 쾌락을 추<br> 구하고 고통을 피한다고 보는 심리적 쾌락주의와, 우리가 쾌락을 증가시키고 고통을 감소시<br> 켜야 한다고 주장하는 윤리적 쾌락주의를 구분한다.<br> 벤담 윤리학의 핵심은 효용의 원리(principle of utility)이다. 여기서 효용은 단순한 실용성이<br> 아니라, 어떤 행위가 이익, 쾌락, 선, 행복을 증진하고 해악, 고통, 악, 불행을 방지하는 경향<br> 을 의미한다. 간단히 말해, 행위의 도덕적 가치는 관련된 모든 사람에게 발생할 것으로 예상</p><p>되는 쾌락과 고통의 전체적 균형에 의해 평가된다.<br> 벤담의 이론은 양적 공리주의(quantitative utilitarianism)라고 불린다. 이는 모든 도덕 판단을<br> 완벽하게 수치화할 수 있다는 뜻이 아니라, 쾌락과 고통의 가치가 주로 양과 여러 차원에<br> 따라 비교된다는 뜻이다. 철학을 읽는 지적 쾌락이 단순히 고상하다는 이유만으로 식사의<br> 육체적 쾌락보다 우월한 것은 아니다. 더 가치 있다면 지속성, 미래 효과, 부정적 결과의 부<br> 재 등 구체적인 차원에서 그 이유를 설명해야 한다.<br> 이 강의는 벤담의 쾌락 계산법(felicific calculus)을 구성하는 일곱 가지 차원을 상세히 다룬<br> 다.<br> 1.<br> Intensity — 강도:쾌락이나 고통이 얼마나 강한가<br> 2.<br> Duration — 지속성:얼마나 오래 지속되는가<br> 3.<br> Certainty — 확실성:실제로 발생할 가능성이 얼마나 높은가<br> 4.<br> Propinquity — 근접성:얼마나 가까운 미래에 발생하는가<br> 5.<br> Fecundity — 생산성/다산성:이후 추가적인 쾌락 또는 고통을 낳을 가능성이 얼마나<br> 높은가<br> 6.<br> Purity — 순수성:쾌락 뒤에 고통이, 또는 고통 뒤에 쾌락이 뒤따르지 않을 가능성이<br> 얼마나 높은가<br> 7.<br> Extent — 범위:몇 명의 사람에게 영향을 미치는가<br> 이 일곱 차원은 정밀한 수학 공식이라기보다, 여러 행위와 정책의 예상 결과를 체계적으로<br> 비교하기 위한 판단의 틀이다. 강의에서는 공공보건 정책, 교육, 중독적 디지털 플랫폼, 형벌,<br> 기후변화, 대학 예산 배분 등의 사례를 통해 이 계산법이 어떻게 적용되는지를 보여준다.<br> 또한 공리주의에는 공평한 집계(impartial aggregation)라는 중요한 특징이 있다. 나의 쾌락<br> 이라고 해서 더 중요하게 계산되는 것이 아니며, 가난한 사람, 수감자, 비인간 동물의 고통<br> 도 사회적 권력이나 발언 능력이 부족하다는 이유만으로 무시될 수 없다. 이 점에서 공리주<br> 의는 평등주의적 잠재력을 지닌다. 그러나 동시에 개인의 권리를 절대적으로 보장하지 않으<br> 며, 다수의 쾌락이 소수의 심각한 고통을 압도할 위험도 있다.<br> 마지막으로 강의는 벤담의 사상을 계몽주의, 법 개혁, 근대적 측정과 행정의 발전이라는 역<br> 사적 맥락에 위치시킨다. 벤담은 오래되었다는 이유만으로 법과 제도가 정당화될 수 없다고<br> 보았으며, 실제로 고통을 줄이고 행복을 증진하는지를 기준으로 제도를 평가하려 했다. 그러<br> 나 강의는 동시에 계량화가 언제나 객관성을 보장하지 않으며, 숫자가 사회적 편견과 전제</p><p>를 감추거나 중요한 경험을 보이지 않게 만들 수도 있음을 지적한다.<br> 핵심적으로, 벤담은 도덕 판단을 보편적 원칙에 대한 복종의 문제에서 경험된 결과를 비교·<br> 평가하는 문제로 이동시킨다. 따라서 중요한 질문은 “이 행위가 보편화될 수 있는가?”만이<br> 아니라, “누구에게, 얼마나 강하게, 얼마나 오래, 얼마나 확실하게, 그리고 어떤 후속 효과와<br> 함께 쾌락과 고통을 산출하는가?”이다.</p>',12)])])}const p=a(n,[["render",s]]);export{m as __pageData,p as default};
